type Invitation = { organizationId: string; inviteeId: string; expiresAt: number; used: boolean };
export function mayJoin(invite: Invitation, userId: string, now: number) {
  return invite.inviteeId === userId && !invite.used && now < invite.expiresAt;
}
// 멤버십 생성과 used 갱신은 같은 트랜잭션에서 처리합니다.

type Membership = { organizationId: string; userId: string; active: boolean };
export function canSwitch(rows: Membership[], userId: string, organizationId: string) {
  return rows.some(row => row.userId === userId
    && row.organizationId === organizationId && row.active);
}
export const organizationCacheKey = (organizationId: string, resource: string) =>
  ['organization', organizationId, resource] as const;

