type Settings = { name: string; timeZone: string; version: number };
export function updateName(current: Settings, expectedVersion: number, name: string) {
  if (current.version !== expectedVersion) throw new Error('다른 변경이 먼저 저장됐습니다.');
  const trimmed = name.trim();
  if (!trimmed || trimmed.length > 80) throw new Error('이름을 확인하세요.');
  return { ...current, name: trimmed, version: current.version + 1 };
}
// 실제 저장도 version 조건이 있는 원자적 UPDATE로 처리합니다.

export function seatsAvailable(limit: number, active: number, reserved: number) {
  if (![limit, active, reserved].every(n => Number.isSafeInteger(n) && n >= 0))
    throw new Error('좌석 수 오류');
  return Math.max(0, limit - active - reserved);
}
// 좌석 확보와 멤버십 생성은 서버 트랜잭션에서 한 번만 처리합니다.

type AuditInput = { organizationId: string; actorId: string; targetId: string;
  action: 'member.invited' | 'settings.updated'; requestId: string };
export function auditEvent(input: AuditInput, now: string) {
  return { organizationId: input.organizationId, actorId: input.actorId,
    targetId: input.targetId, action: input.action, requestId: input.requestId, at: now };
}
